#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "durbin.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  (void)j; /* j is unused but kept for consistency with the original code. */

  for (i = 0; i < n; i++)
    {
      r[i] = (n+1-i);
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_durbin[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  /* Create local restrict-qualified pointers to help the compiler
     reason about aliasing and optimise memory accesses. */
  DATA_TYPE *restrict r_ptr = r;
  DATA_TYPE *restrict y_ptr = y;

  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  int i, k;

#pragma scop
  /* k = 0 initialisation */
  y_ptr[0] = -r_ptr[0];
  beta     = SCALAR_VAL(1.0);
  alpha    = -r_ptr[0];

  for (k = 1; k < _PB_N; k++) {
    /* Recurrence for beta uses alpha from the previous iteration. */
    beta = (SCALAR_VAL(1.0) - alpha * alpha) * beta;

    /* Compute:
         sum = Σ_{i=0}^{k-1} r[k-i-1] * y[i]
       Use two indices (i increasing, j decreasing) to keep the same
       arithmetic order as the original code while reducing index
       arithmetic and improving the compiler's optimisation opportunities. */
    sum = SCALAR_VAL(0.0);
    {
      int j = k - 1;
      for (i = 0; i < k; ++i, --j) {
        sum += r_ptr[j] * y_ptr[i];
      }
    }

    alpha = - (r_ptr[k] + sum) / beta;

    /* Original update (conceptual):
         z[i] = y_old[i] + alpha * y_old[k-1-i],  i = 0..k-1
         y[i] = z[i]
       This can be done in-place without a temporary array by updating
       symmetric pairs (i, j = k-1-i) simultaneously:

         y_new[i] = y_old[i] + alpha * y_old[j]
         y_new[j] = y_old[j] + alpha * y_old[i]

       Since tmp_i and tmp_j hold y_old values, every update uses only
       values from the previous iteration, exactly like the original
       z-buffered version, but with fewer memory accesses. */

    int half = k >> 1; /* floor(k/2) */

    /* Update symmetric pairs [0, k-1], [1, k-2], ... */
    for (i = 0; i < half; ++i) {
      int j = k - 1 - i;
      DATA_TYPE yi = y_ptr[i];
      DATA_TYPE yj = y_ptr[j];

      y_ptr[i] = yi + alpha * yj;
      y_ptr[j] = yj + alpha * yi;
    }

    /* If k is odd, there is a centre element (i == j == k/2) that
       must be updated once:
         y[i] = y_old[i] + alpha * y_old[i]. */
    if (k & 1) {
      int mid = half;
      y_ptr[mid] = y_ptr[mid] + alpha * y_ptr[mid];
    }

    /* Append the new coefficient. */
    y_ptr[k] = alpha;
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(r));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_durbin (n,
		 POLYBENCH_ARRAY(r),
		 POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(r);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
