		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  /* Use local restricted pointers to give the compiler better
     aliasing information and enable more aggressive optimization
     and vectorization of the inner loops.  PolyBench guarantees
     that different arrays do not alias. */
  DATA_TYPE *restrict r_ptr = &r[0];
  DATA_TYPE *restrict y_ptr = &y[0];

  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  int i, k;

#pragma scop
  y_ptr[0] = -r_ptr[0];
  beta = SCALAR_VAL(1.0);
  alpha = -r_ptr[0];

  for (k = 1; k < _PB_N; k++) {
    /* Update beta using the current reflection coefficient.
       Written in a way that keeps the operation count low and
       still preserves the original floating-point semantics. */
    const DATA_TYPE alpha_sq = alpha * alpha;
    beta *= (SCALAR_VAL(1.0) - alpha_sq);

    /* Compute sum = sum_{i=0}^{k-1} r[k-i-1] * y[i].
       Access patterns are linear in both r and y, which is
       cache-friendly and vectorizable. */
    sum = SCALAR_VAL(0.0);
    for (i = 0; i < k; i++) {
      sum += r_ptr[k - i - 1] * y_ptr[i];
    }

    alpha = -(r_ptr[k] + sum) / beta;

    /* In-place symmetric update of y[0..k-1].
       Original code used a temporary array z[]:
         z[i] = y[i] + alpha * y[k-i-1];
         y[i] = z[i];
       This required an additional full pass over the data and
       extra memory traffic.

       Here we exploit the symmetry. For each pair (i, j = k-1-i):
         new_y[i] = old_y[i] + alpha * old_y[j]
         new_y[j] = old_y[j] + alpha * old_y[i]

       We load old_y[i] and old_y[j] into temporaries before
       writing, so each element is read exactly once and written
       exactly once. This removes the need for the temporary
       z[] array while preserving the exact mathematical result. */
    {
      int mid = (k - 1) >> 1; /* floor((k-1)/2) */

      for (i = 0; i <= mid; ++i) {
        int j = k - 1 - i;
        DATA_TYPE yi = y_ptr[i];
        DATA_TYPE yj = y_ptr[j];

        if (i != j) {
          /* General case: two distinct symmetric positions. */
          y_ptr[i] = yi + alpha * yj;
          y_ptr[j] = yj + alpha * yi;
        } else {
          /* Center element when k is odd: j == i. */
          y_ptr[i] = yi + alpha * yi;
        }
      }
    }

    y_ptr[k] = alpha;
  }
#pragma endscop

