  /* Use local restrict-qualified pointers to help the compiler with
     alias analysis and enable better vectorization and scheduling. */
  const DATA_TYPE * restrict r_ = r;
  DATA_TYPE * restrict y_ = y;

  const DATA_TYPE one = SCALAR_VAL(1.0);

  DATA_TYPE alpha;
  DATA_TYPE beta;

  int i, k;

#pragma scop
  /* Initialization identical to the original code. */
  y_[0] = -r_[0];
  beta = one;
  alpha = -r_[0];

  for (k = 1; k < _PB_N; k++) {
    /* Same recurrence as:
         beta = (1 - alpha*alpha) * beta;
       but written to expose common sub-expressions and keep the
       operation count minimal while preserving exact semantics. */
    const DATA_TYPE alpha_sq = alpha * alpha;
    beta *= (one - alpha_sq);

    /* Compute sum = sum_{i=0}^{k-1} r[k-i-1] * y[i]
       Loop order is preserved to keep floating-point behavior identical. */
    DATA_TYPE sum = SCALAR_VAL(0.0);
    for (i = 0; i < k; i++) {
      sum += r_[k - i - 1] * y_[i];
    }

    alpha = - (r_[k] + sum) / beta;

    /* Original code:
         for (i=0; i<k; i++)
           z[i] = y[i] + alpha*y[k-i-1];
         for (i=0; i<k; i++)
           y[i] = z[i];

