             y_new[c] = y_old[c] + alpha * y_old[c] = (1 + alpha)*y_old[c]

       This transformation *preserves* the exact mathematical expression
       for every element and thus the original semantics, while removing
       the O(N) temporary array and cutting one full pass over y. */

    int i_end = k >> 1;  /* floor(k/2) */

    /* Handle symmetric pairs (i, j = k-1-i). */
    for (i = 0; i < i_end; i++) {
      int j = k - i - 1;

      DATA_TYPE yi = y_[i];
      DATA_TYPE yj = y_[j];

      y_[i] = yi + alpha * yj;
      y_[j] = yj + alpha * yi;
    }

    /* If k is odd, there is a central index that pairs with itself. */
    if (k & 1) {
      int mid = i_end;      /* mid = (k-1)/2 */
      DATA_TYPE ym = y_[mid];
      y_[mid] = ym + alpha * ym;  /* (1 + alpha) * ym */
    }

    y_[k] = alpha;
  }
#pragma endscop

