		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  /* Local restricted views of the arrays.
   * r is read-only; y is read-write.
   */
  const DATA_TYPE * __restrict r_ptr = r;
  DATA_TYPE       * __restrict y_ptr = y;

  DATA_TYPE alpha;
  DATA_TYPE beta;

  int k;

#pragma scop
  /* Initial conditions. */
  const DATA_TYPE minus_r0 = -r_ptr[0];
  y_ptr[0] = minus_r0;
  beta = SCALAR_VAL(1.0);
  alpha = minus_r0;

  for (k = 1; k < _PB_N; k++) {
    /* Update beta: beta_k = (1 - alpha_{k-1}^2) * beta_{k-1}. */
    beta *= (SCALAR_VAL(1.0) - alpha * alpha);

    /* Compute the scalar product:
     *   sum = sum_{i=0}^{k-1} r[k-1-i] * y[i]
     *
     * Implemented with pointers to avoid repeated index
     * arithmetic inside the loop.
     */
    DATA_TYPE sum = SCALAR_VAL(0.0);

    const DATA_TYPE * __restrict r_k = r_ptr + (k - 1);
    const DATA_TYPE * __restrict y_i = y_ptr;

    for (int i = 0; i < k; i++) {
      sum += (*r_k) * (*y_i);
      --r_k;
      ++y_i;
    }

    /* Next reflection coefficient alpha_k. */
    alpha = -(r_ptr[k] + sum) / beta;

    /* In-place symmetric update of y[0..k-1].
     *
     * Original code:
     *   for (i = 0; i < k; i++)
     *     z[i] = y[i] + alpha * y[k-i-1];
     *   for (i = 0; i < k; i++)
     *     y[i] = z[i];
     *
     * This computes, for each index j:
     *   y_new[j] = y_old[j] + alpha * y_old[k-1-j]
     *
     * We can perform this in-place without a temporary array
     * by updating pairs (i, j = k-1-i) simultaneously:
     *   (y[i], y[j]) <- (y[i] + alpha*y[j],
     *                    y[j] + alpha*y[i])
     *
     * For the middle element when k is odd (i == j), the
     * update reduces to:
     *   y[i] <- y[i] + alpha * y[i]
     * which matches the original computation.
     */
    int i = 0;
    int j = k - 1;

    while (i < j) {
      const DATA_TYPE yi = y_ptr[i];
      const DATA_TYPE yj = y_ptr[j];

      y_ptr[i] = yi + alpha * yj;
      y_ptr[j] = yj + alpha * yi;

      ++i;
      --j;
    }

    /* Handle the central element when k is odd. */
    if (i == j) {
      const DATA_TYPE yi = y_ptr[i];
      y_ptr[i] = yi + alpha * yi;
    }

    /* Append alpha at position k. */
    y_ptr[k] = alpha;
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(r));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_durbin (n,
		 POLYBENCH_ARRAY(r),
		 POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(r);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
